#include <stdio.h>
int main(void){PIXELFORMATDESCRIPTOR p={0};HWND w;HDC dc;HGLRC c;int f;unsigned char center[4]={0},edge[4]={0};w=CreateWindowA("STATIC","WineMetalGL point",WS_OVERLAPPEDWINDOW,0,0,64,64,0,0,0,0);if(!w)return 11;dc=GetDC(w);p.nSize=sizeof(p);p.nVersion=1;p.dwFlags=PFD_DRAW_TO_WINDOW|PFD_SUPPORT_OPENGL;p.iPixelType=PFD_TYPE_RGBA;p.cColorBits=32;f=ChoosePixelFormat(dc,&p);if(!f||!SetPixelFormat(dc,f,&p))return 12;c=wglCreateContext(dc);if(!c||!wglMakeCurrent(dc,c))return 13;glViewport(0,0,64,64);glClearColor(0,0,0,1);glClear(GL_COLOR_BUFFER_BIT);glPointSize(9);glColor4f(1,0,0,1);glBegin(GL_POINTS);glVertex3f(0,0,0);glEnd();glReadPixels(32,32,1,1,GL_RGBA,GL_UNSIGNED_BYTE,center);glReadPixels(28,32,1,1,GL_RGBA,GL_UNSIGNED_BYTE,edge);if(center[0]<245||edge[0]<200)return 14;printf("WINEMETALGL_FIXED_POINT_SIZE_OK\n");wglMakeCurrent(0,0);wglDeleteContext(c);ReleaseDC(w,dc);DestroyWindow(w);return 0;}
